// Runtime access to the processed asset manifest (generated by scripts/process-assets.ts).
// Every lookup can return undefined: callers must fall back to procedural placeholders,
// so the game runs even if no assets were fetched.
import manifestJson from '../generated/asset-manifest.json';

export type AssetTier = 'high' | 'low';

interface ImageEntry {
  webp: string;
  ktx2?: string;
  w: number;
  h: number;
}
interface AudioEntry {
  ogg: string;
  m4a: string;
  duration: number;
}
interface TierManifest {
  images: Record<string, ImageEntry>;
  atlases: Record<string, { pages: string[]; frames: string[] }>;
  audio: Record<string, AudioEntry>;
  fonts: Record<string, string>;
}

const manifest = manifestJson as unknown as { tiers: Record<AssetTier, TierManifest> };

let tier: AssetTier = 'high';

export function setAssetTier(t: AssetTier): void {
  tier = t;
}

export function getAssetTier(): AssetTier {
  return tier;
}

const base = import.meta.env.BASE_URL.replace(/\/$/, '');
const url = (u: string) => `${base}${u}`;

export function imageUrl(id: string): string | undefined {
  const e = manifest.tiers[tier]?.images[id];
  return e ? url(e.webp) : undefined;
}

export function atlasPages(name: string): string[] {
  return (manifest.tiers[tier]?.atlases[name]?.pages ?? []).map(url);
}

export function listAudio(prefix = ''): string[] {
  return Object.keys(manifest.tiers[tier]?.audio ?? {}).filter((k) => k.startsWith(prefix));
}

let preferM4a: boolean | null = null;

/** Pick Ogg where supported, AAC otherwise (older iPad Safari). */
export function audioUrl(id: string): string | undefined {
  const e = manifest.tiers[tier]?.audio[id];
  if (!e) return undefined;
  if (preferM4a === null) {
    const a = typeof document !== 'undefined' ? document.createElement('audio') : null;
    preferM4a = !a || a.canPlayType('audio/ogg; codecs="vorbis"') === '';
  }
  return url(preferM4a ? e.m4a : e.ogg);
}

export function fontUrls(): Record<string, string> {
  return Object.fromEntries(Object.entries(manifest.tiers[tier]?.fonts ?? {}).map(([k, v]) => [k, url(v)]));
}
